struct Base {
    Base(int a) {}
    Base(const char* s) {}
    template <typename T>
    Base(T&& t) {} // Template constructors inherited
};

struct Derived : Base {
    using Base::Base; // Inherit all constructors

    // Can define own constructors alongside inherited ones
    Derived(bool flag) : Base(flag ? 1 : 0) {}
};

// Derived d1(10);         // Uses inherited Base(int)
// Derived d2("hello");    // Uses inherited Base(const char*)
// Derived d3(true);       // Uses derived ctor
// Derived d4(4.5f);       // Uses inherited template ctor
// Note: Explicitly deleted or private ctors are NOT inherited.
